# Define the possible actions (up, down, left, right)
actions = [(0, -1), (0, 1), (-1, 0), (1, 0)]

def get_neighbors(state, grid):
    neighbors = []
    x, y = state
    for dx, dy in actions:
        nx, ny = x + dx, y + dy
        if (nx >= 0 and ny >= 0 and nx < len(grid) and ny < len(grid[0]) and 
            grid[nx][ny] != "X"):
            neighbors.append((nx, ny))
    return neighbors

def get_distance(state1, state2):
    x1, y1 = state1
    x2, y2 = state2
    return abs(x1 - x2) + abs(y1 - y2)

def get_expected_value(state, policy, grid):
    queue = deque([(state, 0)])
    visited = set([state])
    while queue:
        current_state, distance = queue.popleft()
        if current_state == goal:
            return distance
        for neighbor in get_neighbors(current_state, grid):
            if neighbor not in visited:
                queue.append((neighbor, distance + 1))
                visited.add(neighbor)
    return float('inf')

def cluster_states(grid, policy):
    # Get all states from the grid
    states = [(x, y) for x in range(len(grid)) for y in range(len(grid[0])) if grid[x][y] != "X"]

    # Initialize clusters and corresponding visited sets
    clusters = {}
    visited = set(states)

    # Iterate over each state
    for state in states:
        if state not in visited:
            continue

        # Get all reachable states from this cluster
        queue = deque([(state, 0)])
        cluster_states = [state]
        visited_from_cluster = set([state])
        while queue:
            current_state, distance = queue.popleft()
            for neighbor in get_neighbors(current_state, grid):
                if (neighbor not in visited or 
                    get_expected_value(neighbor, policy, grid) > distance + 1 and
                    get_distance(current_state, goal) == get_distance(neighbor, goal)):
                    continue
                if neighbor not in visited_from_cluster:
                    queue.append((neighbor, distance + 1))
                    cluster_states.append(neighbor)
                    visited_from_cluster.add(neighbor)

        # Add the states to a new cluster and mark them as visited
        clusters[tuple(sorted(cluster_states))] = sorted(cluster_states)
        for s in cluster_states:
            visited.remove(s)

    return clusters

