                                  ((len(grid) - i) % len(grid[0]), j),
                                  (j, (len(grid[0]) - j - 1)),
                                  ((len(grid[0]) - j) % len(grid), (len(grid) - i - 1))]
                reflected_states = [(i, len(grid[0]) - j - 1),
                                    ((len(grid[0]) - j) % len(grid), i)]

                for s in rotated_states + reflected_states:
