import numpy as np

# Define the grid world environment.
grid = np.array([[0,"X",5],[1,3,4],[2,"X",6]])
goal = 6
start = 0

# Convert the grid into a dictionary for easier manipulation and look up of cell values.
env_dict = {}
for i in range(len(grid)):
    for j in range(len(grid[i])):
        env_dict[(i,j)] = (grid[i][j], i, j)

# Define function to calculate Manhattan distance heuristic for A* algorithm
def manhattan_distance(state, goal):
    return abs(state[1] - env_dict[goal][1]) + abs(state[2] - env_dict[goal][2])

# Implement a simple clustering method based on symmetry.
def cluster_states(env_dict, start_state, goal_state):
    clusters = {}

    # Define functions for rotating and reflecting the environment
    def rotate(grid, angle_degrees=90): 
        return np.rot90(np.array(grid), k=1 if angle_degrees==90 else -1)

    def reflect(grid, axis='x'): 
        grid_array = np.array(grid)
        if axis == 'y':
            return np.fliplr(grid_array)
        elif axis == 'x':
            return np.flipud(grid_array)

    # Perform symmetry operations and create a set of equivalent states
    symmetries = {'identity': lambda x: x,
                  '90_degrees': rotate,
                  '180_degrees': lambda x: rotate(x, 180),
                  '270_degrees': rotate,
                  'x_axis_flip': reflect,
                  'y_axis_flip': reflect}

    # Iterate over all possible symmetries and create a set of equivalent states
    for symmetry_name, symmetry_func in symmetries.items():
        temp_env_dict = {}

        # Apply the current symmetry to each state
        for (i,j), value in env_dict.items():
            new_state = ((value[0], 
                          symmetry_func(env_dict[(i,j)][1]) - np.min([k[1] for k in env_dict.values()]),
                          symmetry_func(env_dict[(i,j)][2]) - np.min([k[2] for k in env_dict.values()])),
                         i, j)

            # Convert the new state into a string representation to use as key
            temp_env_dict[tuple(new_state)] = value

        # Determine equivalent states based on actionability and distance to goal        
        for (i,j), state_value in temp_env_dict.items():
            if manhattan_distance(state_value, goal) < 10:
                clusters.setdefault(tuple([state_value[0],manhattan_distance(state_value,goal)]), []).append(temp_env_dict[(i,j)])

    return clusters

